cache={}; evidence=set(); checks=[]
def rows(path):
    evidence.add(path)
    if path not in cache:
        p=ROOT/path
        with (gzip.open(p,'rt') if path.endswith('.gz') else p.open()) as f: cache[path]=list(csv.DictReader(f,delimiter='\t'))
    return cache[path]
def pick(path,**kw): return next(r for r in rows(path) if all(r[k]==str(v) for k,v in kw.items()))
def num(v): return float(v)
def fmt(v):
    try:
        x=float(v)
        if x==0: return '0'
        return f'{x:.4g}'
    except: return str(v)
def table_write(name,data,fields=None):
    if not fields: fields=list(data[0]) if data else ['note']
    with (OUT/name).open('w') as f:
        w=csv.DictWriter(f,fieldnames=fields,delimiter='\t',extrasaction='ignore');w.writeheader();w.writerows(data)
def check(label,condition,details=''):
    checks.append(dict(check=label,passed=bool(condition),details=details))
    if not condition: raise AssertionError(label+': '+details)
def mean_col(rs,k): return statistics.mean(float(r[k]) for r in rs)
