    return '<figure><h3>'+esc(title)+'</h3><a href="sources/'+esc(path,quote=True)+'"><img loading="lazy" src="sources/'+esc(path,quote=True)+'" alt="'+esc(title,quote=True)+'"></a><figcaption>'+esc(caption)+'</figcaption><p class="source">'+esc(f['figure_id'])+' · '+esc(f['analysis_ids'])+' · '+link(path,'PNG')+(' · '+link(f['pdf_path'],'PDF') if f['pdf_path'] else '')+' · '+link(f['script_path'],'Script')+' · '+link(f['result_table_path'].split(';')[0],'Table')+'</p></figure>'
